testcase.name:
test_templated_choices[ choices: |
 {%- for c in ['one', 'two', 'three'] %}
 - {{ c }}
 {%- endfor %}
 ]

test_templated_choices[ choices: |
 {%- for c in ['one', 'two', 'three'] %}
 {{ c }}: null
 {%- endfor %}
 ]

test_templated_choices[ choices: |
 {%- for c in ['one', 'two', 'three'] %}
 {{ c|upper }}: {{ c }}
 {%- endfor %}
 ]

test_templated_choices[ choices: |
 {%- for c in ['one', 'two', 'three'] %}
 - [{{ c|upper }}, {{ c }}]
 {%- endfor %}
 ]

test_templated_choices[ choices: |
 {%- for c in ['one', 'two', 'three'] %}
 {{ c|upper }}:
 value: {{ c }}
 {%- endfor %}
 ]

test_templated_choices[ choices: |
 {%- for c in ['one', 'two', 'three'] %}
 {{ c|upper }}:
 value: {{ c }}
 validator: "{% raw %}{% if false %}Validation error{% endif %}{% endraw %}"
 {%- endfor %}
 ]

test_multiselect_choices_with_templated_default_value[ type: yaml
 choices:
 one: '{value: [1, null]}'
 two: '{value: [2, null]}'
 three: '{value: [3, null]}'
 multiselect: true
 default: |
 {%- if true %}
 - {value: [1, null]}
 - {value: [3, null]}
 {%- endif %}
 -expected8]

test_multiselect_choices_with_templated_default_value[ type: yaml
 choices:
 one: '{value: "[1]"}'
 two: '{value: "[2]"}'
 three: '{value: "[3]"}'
 multiselect: true
 default: |
 {%- if true %}
 - {value: '[1]'}
 - {value: '[3]'}
 {%- endif %}
 -expected10]
